import{_ as t,o,c as r,a2 as n}from"./chunks/framework.il0noOp3.js";const m=JSON.parse('{"title":"Changelog","description":"Release history and version changelog for AzureScout.","frontmatter":{"description":"Release history and version changelog for AzureScout."},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),a={name:"changelog.md"};function s(d,e,c,i,l,g){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>The full changelog is maintained in the repository root and rendered on GitHub.</p><p><a href="https://github.com/thisismydemo/azure-scout/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">View CHANGELOG.md on GitHub</a></p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>AzureScout follows <a href="https://keepachangelog.com/en/1.1.0/" target="_blank" rel="noreferrer">Keep a Changelog</a> format and <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><table tabindex="0"><thead><tr><th>Version</th><th>Highlights</th></tr></thead><tbody><tr><td><strong>v2.5.2</strong> (2026-07-25)</td><td><strong>Determinism</strong> — a whole report category could silently vanish from a run. A job-wait race meant a still-<code>NotStarted</code> job was never waited on, then harvested and destroyed empty, so <code>Compute.json</code> came back 5,158 bytes on one run and 470 on the next. Both the wait loop and the batch filter now treat every non-terminal state as pending, a dropped category now warns instead of failing silently, and a machine without Excel gets a plain explanation rather than a raw COM <code>0x80040154</code> error</td></tr><tr><td><strong>v2.5.1</strong> (2026-07-25)</td><td><strong>Seven live-run fixes</strong> — a full inventory run could not complete against a real tenant; extraction and processing succeeded, then the reporting layer threw after every worksheet had been built. Fixes an uninitialised extraction variable, 41 <code>.IsPresent</code> reads on untyped parameters, Excel styling/tables on empty worksheets, VM property names the collector never emitted, 29 unguarded worksheet dereferences, 10 pivot titles read before assignment, and a Markdown string-interpolation bug. All seven were found by running against live Azure, not by the test suite</td></tr><tr><td><strong>v2.5.0</strong> (2026-07-25)</td><td><strong>One collection pass</strong> — a combined inventory + assessment run now queries Azure once instead of twice. The assessment shapes its scalars from the rows the inventory pass already fetched (<code>ConvertFrom-ScoutInventory</code>, <code>-FromInventory</code>); only the Defender for SQL pricing lookup still reaches Resource Graph, because it reads a table inventory does not collect. Assessment-only runs are unchanged</td></tr><tr><td><strong>v2.4.0</strong> (2026-07-25)</td><td><strong>One command</strong> — inventory and assessment became modes of <code>Invoke-AzureScout</code> rather than two cmdlets (<code>-Assessment</code>, <code>-CollectOnly</code>, <code>-FromCollect</code>); assessment mode now honours the inventory sign-in parameters; <code>-OutputFormat</code> widened to accept several renderers in one run. A <strong>guided setup wizard</strong> opens when <code>Invoke-AzureScout</code> is run with no parameters at a terminal, and never fires in CI. <code>Invoke-ScoutAssessment</code> is deprecated for removal in v3.0.0</td></tr><tr><td><strong>v2.3.0</strong> (2026-07-25)</td><td>Run isolation (each invocation gets its own run folder, <code>-RunName</code>, <code>-Force</code>, <code>Clear-AZSCCacheFolder -OlderThan</code>), the caller&#39;s subscription context restored after multi-subscription runs, a post-login management-group probe, <strong>Azure DevOps inventory</strong> via <code>-IncludeDevOps</code> (five worksheets plus service-connection-to-subscription cross-reference), a composite <code>action.yml</code> for GitHub Actions, and new automation, category-reference, and validation-matrix documentation</td></tr><tr><td><strong>v2.2.0</strong> (2026-07-24)</td><td>Four new report tiers (<code>Word</code>, <code>EChartsDashboard</code>, <code>Pdf</code>, <code>JsonEvidence</code>), Excel visual dashboard tabs, a much richer interactive React report (topology, MG hierarchy, KPI cards, Governance section, drill-downs) + <code>report.pbit</code> generation, new offline analysis (<code>Get-ScoutInventoryDrift</code>, <code>Get-ScoutCostAnomaly</code>, <code>Get-ScoutIacGap</code>), IoT deep coverage (DPS + Digital Twins), tag aggregation, deeper Database/Analytics/IoT rule automation, collector/pipeline resilience, assessment config load/save (<code>Import-ScoutConfig</code>/<code>Export-ScoutConfig</code>), a CI pipeline, a real <code>azure-inventory</code> workflow, and five v1 inventory bug fixes</td></tr><tr><td><strong>v2.1.0</strong> (2026-07-23)</td><td>Native governance collector (<code>Import-Governance</code>, no more AzGovViz dependency by default), unattended one-command pipeline (<code>Invoke-ScoutPipeline</code>), and a React report + cross-run drift tracking (<code>-OutputFormat React</code>, <code>Get-ScoutDrift</code>)</td></tr><tr><td><strong>v2.0.0</strong></td><td><strong>CAF/WAF Assessment Platform</strong> — read-only assessment engine (139 rules across 8 CAF design areas + 5 WAF pillars), ARG collect layer, AzGovViz/Advisor/ARG ingest, ALZ benchmark, tiered reporting (Power BI / HTML / OpenXML PowerPoint / Excel / JSON), per-domain analytics via <code>Invoke-ScoutAssessment</code>. Runtime-verified offline + live tenant. Breaking: <code>findings.json</code> contract; assessment requires PowerShell 7</td></tr><tr><td><strong>v1.0.0</strong></td><td>Full rename to AzureScout (AZSC prefix), 154 ARM modules, 17 Entra ID modules, Excel + JSON + Markdown + AsciiDoc output, draw.io diagrams, permission pre-flight, category filtering</td></tr></tbody></table>',6)])])}const h=t(a,[["render",s]]);export{m as __pageData,h as default};
